select tfo.id, tfo.code, tfo.transfer_direction AS transferDirection, tfo.approve_status AS approveStatus, tfo.invalid_status AS invalidStatus, tod.id as detailId, tod.sku_id AS skuId, tod.sku_no AS skuNo, tfo.bill_date AS billDate, tod.qty, tod.unit, tfo.out_warehouse_id AS outWarehouseId, tfo.out_warehouse_name AS outWarehouseName, tod.remark, tfo.approve_user_name AS approveUserName, tfo.create_user_name AS createUserName, tfo.create_time AS createTime, tod.out_warehouse_location AS outWarehouseLocation, tfo.source_code AS sourceCode from transfer_out tfo inner join transfer_out_detail tod on tfo.id = tod.main_id and tod.is_deleted = false
${params.sqlMap.default} and tfo.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
tfo.id desc,tod.id asc

select tfo.id, tfo.code, tfo.transfer_direction AS transferDirection, tfo.approve_status AS approveStatus, tfo.invalid_status AS invalidStatus, tod.sku_id AS skuId, tod.sku_no AS skuNo, tfo.bill_date AS billDate, tod.qty, tod.unit, tfo.out_warehouse_id AS outWarehouseId, tfo.out_warehouse_name AS outWarehouseName, tod.remark, tfo.approve_user_name AS approveUserName, tfo.create_user_name AS createUserName, tfo.create_time AS createTime, tod.out_warehouse_location AS outWarehouseLocation, tfo.source_code AS sourceCode from transfer_out tfo inner join transfer_out_detail tod on tfo.id = tod.main_id and tod.is_deleted = false
${params.sqlMap.default} and tfo.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
tfo.id desc,tod.id asc

select tfo.code as source_code, tfo.id as source_id, tod.id as source_detail_id, tfo.transfer_direction as transfer_direction, tfo.approve_status as approve_status, tod.sku_id as sku_id, tod.sku_no as sku_no, tod.qty as qty, tfo.bill_date as bill_date, tfo.out_warehouse_id as out_warehouse_id, tfo.out_warehouse_name as out_warehouse_name, tfo.in_warehouse_id as in_warehouse_id, tfo.in_warehouse_name as in_warehouse_name, tod.out_warehouse_location as out_warehouse_location, tod.remark from transfer_out_detail tod inner join transfer_out tfo on tfo.id = tod.main_id and tod.is_deleted = false
tfo.is_deleted = false and tod.id in
